function deriveTitle(text4, role2) {
  const lines = text4.replace(/\r\n/g, "\n").split("\n");
  let inFence = false;
  for (const line of lines) {
    const trimmed2 = line.trim();
    if (inFence) {
      if (trimmed2.startsWith("```")) inFence = false;
      continue;
    }
    if (trimmed2.startsWith("```")) {
      inFence = true;
      continue;
    }
    if (trimmed2 === "") continue;
    if (/^(-{3,}|\*{3,}|_{3,})$/.test(trimmed2)) continue;
    if (trimmed2.startsWith("|")) continue;
    const cleaned = trimmed2.replace(/^#{1,6}\s+/, "").replace(/^>\s*/, "").replace(/^[-*+]\s+/, "").replace(/^\d+[.)]\s+/, "").replace(/^\[[ xX]\]\s+/, "").replace(/!\[[^\]]*\]\([^)]*\)/g, "").replace(/\[([^\]]*)\]\([^)]*\)/g, "$1").replace(/[*_~`]/g, "").replace(/\s+/g, " ").trim();
    if (cleaned !== "") {
      const limit = 64;
      return cleaned.length > limit ? `${cleaned.slice(0, limit)}\u2026` : cleaned;
    }
  }
  return role2 === "user" ? "\u6211\u7684\u63D0\u95EE" : "AI \u56DE\u590D";
}

