    '  $sha = ($r.Substring(0, $tab) -split " ")[1]',
    "  $curMap[$path] = $sha",
    "}",
    "$targetMap = @{}",
    "foreach ($r in @($targetOut)) {",
    "  if (-not $r) { continue }",
    '  $tab = $r.IndexOf("`t"); $path = $r.Substring($tab + 1)',
    '  $sha = ($r.Substring(0, $tab) -split " ")[2]',
